import { useState, useRef, useEffect } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
  Send,
  Plus,
  Menu,
  Settings,
  LogOut,
  Sun,
  Moon,
  Trash2,
  MessageSquare,
} from "lucide-react";
import { useTheme } from "next-themes";

interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  timestamp: Date;
}

interface Conversation {
  id: string;
  title: string;
  messages: Message[];
  createdAt: Date;
}

export default function Chat() {
  const [, navigate] = useLocation();
  const { theme, setTheme } = useTheme();
  const [conversations, setConversations] = useState<Conversation[]>([
    {
      id: "1",
      title: "Product Performance Analysis",
      messages: [
        {
          id: "m1",
          role: "assistant",
          content:
            "Hello! I'm Nova, your AI product analyst. I can help you analyze your products, understand market trends, optimize pricing, identify feature gaps, and much more. What product would you like to analyze today?",
          timestamp: new Date(Date.now() - 3600000),
        },
        {
          id: "m2",
          role: "user",
          content: "I want to analyze my SaaS product and understand how to improve it",
          timestamp: new Date(Date.now() - 3500000),
        },
        {
          id: "m3",
          role: "assistant",
          content:
            "Great! To provide you with meaningful insights, let me ask a few questions:\n\n1. What's your product category (e.g., project management, CRM, analytics)?\n2. How many customers do you currently have?\n3. What's your monthly churn rate?\n4. What are your top 3 customer complaints or feature requests?\n\nWith this information, I can help you identify growth opportunities and areas for improvement.",
          timestamp: new Date(Date.now() - 3400000),
        },
        {
          id: "m4",
          role: "user",
          content: "It's a project management tool, 500 customers, 5% churn, and customers want better mobile experience",
          timestamp: new Date(Date.now() - 3300000),
        },
        {
          id: "m5",
          role: "assistant",
          content:
            "Excellent data point! Here's my analysis:\n\n📊 **Market Position**: With 5% churn, you're in a healthy range. Here are my recommendations:\n\n1. **Mobile App Development** - 87% of successful project management tools have native mobile apps. This could reduce churn by 2-3%.\n\n2. **Feature Priorities**:\n   - Task assignment on mobile (high demand)\n   - Real-time notifications (medium priority)\n   - Offline task viewing (growing demand)\n\n3. **Pricing Opportunities**:\n   - Mobile-exclusive tier could add $50k/month revenue\n   - Premium support for enterprise customers\n\n4. **Competitive Advantage**:\n   - Focus on collaboration features\n   - Integration with Slack/Teams\n\nWould you like me to dive deeper into any of these areas?",
          timestamp: new Date(Date.now() - 3200000),
        },
      ],
      createdAt: new Date(Date.now() - 3600000),
    },
  ]);

  const [currentConversationId, setCurrentConversationId] = useState("1");
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);

  const currentConversation = conversations.find(
    (c) => c.id === currentConversationId
  );

  useEffect(() => {
    if (scrollRef.current) {
      setTimeout(() => {
        scrollRef.current?.scrollIntoView({ behavior: "smooth" });
      }, 0);
    }
  }, [currentConversation?.messages]);

  const handleSendMessage = () => {
    if (!input.trim() || !currentConversation) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: "user",
      content: input,
      timestamp: new Date(),
    };

    setConversations((prev) =>
      prev.map((conv) =>
        conv.id === currentConversationId
          ? { ...conv, messages: [...conv.messages, userMessage] }
          : conv
      )
    );

    setInput("");
    setIsLoading(true);

    setTimeout(() => {
      const responses = [
        "That's an insightful question. Let me analyze this aspect of your product...",
        "Based on market trends and your current metrics, here's what I recommend...",
        "I can see how this relates to your overall product strategy. Here are my thoughts...",
        "This is a critical area for improvement. Consider implementing...",
        "Great observation. This aligns with industry best practices for SaaS products.",
      ];

      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: "assistant",
        content: responses[Math.floor(Math.random() * responses.length)],
        timestamp: new Date(),
      };

      setConversations((prev) =>
        prev.map((conv) =>
          conv.id === currentConversationId
            ? { ...conv, messages: [...conv.messages, assistantMessage] }
            : conv
        )
      );
      setIsLoading(false);
    }, 1000);
  };

  const createNewConversation = () => {
    const newConv: Conversation = {
      id: Date.now().toString(),
      title: "New Product Analysis",
      messages: [
        {
          id: "m1",
          role: "assistant",
          content:
            "Hello! I'm Nova, your AI product analyst. I can help you analyze your products, understand market trends, optimize pricing, identify feature gaps, and much more. What product would you like to analyze today?",
          timestamp: new Date(),
        },
      ],
      createdAt: new Date(),
    };
    setConversations((prev) => [newConv, ...prev]);
    setCurrentConversationId(newConv.id);
  };

  const deleteConversation = (id: string) => {
    const remaining = conversations.filter((c) => c.id !== id);
    setConversations(remaining);
    if (currentConversationId === id && remaining.length > 0) {
      setCurrentConversationId(remaining[0].id);
    }
  };

  return (
    <div className="flex h-screen bg-background text-foreground dark:bg-zinc-950">
      {/* Sidebar */}
      <aside
        className={`${
          sidebarOpen ? "w-64" : "w-0"
        } border-r border-border bg-muted/30 flex flex-col transition-all duration-300 overflow-hidden`}
      >
        <div className="p-4 border-b border-border">
          <Button
            className="w-full rounded-lg gap-2 justify-start"
            size="sm"
            onClick={createNewConversation}
            data-testid="button-new-chat"
          >
            <Plus className="h-4 w-4" />
            New Chat
          </Button>
        </div>

        <ScrollArea className="flex-1">
          <div className="p-4 space-y-2">
            {conversations.map((conv) => (
              <div key={conv.id} className="group relative">
                <button
                  onClick={() => setCurrentConversationId(conv.id)}
                  className={`w-full text-left px-4 py-3 rounded-lg text-sm transition-colors truncate ${
                    currentConversationId === conv.id
                      ? "bg-primary/20 text-primary font-medium"
                      : "text-muted-foreground hover:bg-muted/50"
                  }`}
                  data-testid={`button-conversation-${conv.id}`}
                >
                  <div className="flex items-center gap-2">
                    <MessageSquare className="h-3.5 w-3.5 flex-shrink-0" />
                    <span className="truncate">{conv.title}</span>
                  </div>
                </button>
                <button
                  onClick={() => deleteConversation(conv.id)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity p-1 hover:bg-destructive/20 rounded"
                  data-testid={`button-delete-${conv.id}`}
                >
                  <Trash2 className="h-3 w-3 text-destructive" />
                </button>
              </div>
            ))}
          </div>
        </ScrollArea>

        <div className="p-4 border-t border-border space-y-2">
          <Button
            variant="ghost"
            className="w-full justify-start gap-2 text-muted-foreground"
            size="sm"
          >
            <Settings className="h-4 w-4" />
            Settings
          </Button>
          <Button
            variant="ghost"
            className="w-full justify-start gap-2 text-muted-foreground"
            size="sm"
            onClick={() => navigate("/")}
            data-testid="button-back-home"
          >
            <LogOut className="h-4 w-4" />
            Back to Home
          </Button>
        </div>
      </aside>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col">
        {/* Header */}
        <header className="border-b border-border bg-background/50 backdrop-blur-sm px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setSidebarOpen(!sidebarOpen)}
              className="md:hidden"
              data-testid="button-toggle-sidebar"
            >
              <Menu className="h-5 w-5" />
            </Button>
            <div className="hidden sm:flex items-center gap-2">
              <div className="h-8 w-8 rounded-lg bg-primary flex items-center justify-center text-primary-foreground font-bold">
                N
              </div>
              <span className="font-semibold">Product Analyzer</span>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
              data-testid="button-theme-toggle"
            >
              {theme === "dark" ? (
                <Sun className="h-5 w-5" />
              ) : (
                <Moon className="h-5 w-5" />
              )}
            </Button>
          </div>
        </header>

        {/* Messages Area */}
        <ScrollArea className="flex-1">
          <div className="p-6 space-y-4 max-w-4xl mx-auto w-full pb-32">
            {currentConversation?.messages.map((msg) => (
              <div
                key={msg.id}
                className={`flex gap-4 ${
                  msg.role === "user" ? "justify-end" : "justify-start"
                }`}
              >
                {msg.role === "assistant" && (
                  <Avatar className="h-8 w-8 flex-shrink-0 mt-1">
                    <AvatarFallback className="bg-primary text-primary-foreground text-xs font-bold">
                      N
                    </AvatarFallback>
                  </Avatar>
                )}

                <div
                  className={`rounded-2xl px-5 py-3 max-w-2xl shadow-sm ${
                    msg.role === "user"
                      ? "bg-primary text-primary-foreground rounded-br-sm"
                      : "bg-muted text-foreground border border-border rounded-bl-sm"
                  }`}
                >
                  <p className="text-sm leading-relaxed whitespace-pre-wrap">
                    {msg.content}
                  </p>
                </div>

                {msg.role === "user" && (
                  <Avatar className="h-8 w-8 flex-shrink-0 mt-1">
                    <AvatarImage src="https://github.com/shadcn.png" />
                    <AvatarFallback>U</AvatarFallback>
                  </Avatar>
                )}
              </div>
            ))}

            {isLoading && (
              <div className="flex gap-4">
                <Avatar className="h-8 w-8 flex-shrink-0 mt-1">
                  <AvatarFallback className="bg-primary text-primary-foreground text-xs font-bold">
                    N
                  </AvatarFallback>
                </Avatar>
                <div className="bg-muted text-foreground border border-border rounded-2xl rounded-bl-sm px-5 py-3 flex gap-1">
                  <div className="w-2 h-2 bg-foreground/40 rounded-full animate-bounce" />
                  <div
                    className="w-2 h-2 bg-foreground/40 rounded-full animate-bounce"
                    style={{ animationDelay: "150ms" }}
                  />
                  <div
                    className="w-2 h-2 bg-foreground/40 rounded-full animate-bounce"
                    style={{ animationDelay: "300ms" }}
                  />
                </div>
              </div>
            )}
            <div ref={scrollRef} />
          </div>
        </ScrollArea>

        {/* Input Area */}
        <div className="border-t border-border bg-background/50 backdrop-blur-sm p-6 fixed bottom-0 right-0 left-64 dark:left-64 md:left-64">
          <div className="max-w-4xl mx-auto">
            <div className="flex gap-3">
              <Input
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyPress={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    handleSendMessage();
                  }
                }}
                placeholder="Ask about your product performance, market trends, pricing strategy..."
                className="rounded-full border-border bg-muted/30 focus:bg-muted/50"
                disabled={isLoading}
                data-testid="input-message"
              />
              <Button
                onClick={handleSendMessage}
                disabled={isLoading || !input.trim()}
                size="icon"
                className="rounded-full h-10 w-10"
                data-testid="button-send"
              >
                <Send className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}